   212→// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
   213→// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
   214→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   215→	// Check if checkpoint already exists (multi-session support)
   216→	var existingMetadata *CommittedMetadata
   217→	metadataPath := basePath + paths.MetadataFileName
   218→	if entry, exists := entries[metadataPath]; exists {
   219→		// Read existing metadata to get session count
   220→		existing, err := s.readMetadataFromBlob(entry.Hash)
   221→		if err == nil {
   222→			existingMetadata = existing
   223→			// Archive existing session files to numbered subfolder
   224→			s.archiveExistingSession(basePath, existingMetadata, entries)
   225→		}
   226→	}
   227→
   228→	// Write transcript (from in-memory content or file path)
   229→	if err := s.writeTranscript(opts, basePath, entries); err != nil {
   230→		return err
   231→	}
   232→
   233→	// Write prompts
   234→	if len(opts.Prompts) > 0 {
   235→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   236→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   237→		if err != nil {
   238→			return err
   239→		}
   240→		entries[basePath+paths.PromptFileName] = object.TreeEntry{
   241→			Name: basePath + paths.PromptFileName,
   242→			Mode: filemode.Regular,
   243→			Hash: blobHash,
   244→		}
   245→	}
   246→
   247→	// Write context
   248→	if len(opts.Context) > 0 {
   249→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   250→		if err != nil {
   251→			return err
   252→		}
   253→		entries[basePath+paths.ContextFileName] = object.TreeEntry{
   254→			Name: basePath + paths.ContextFileName,
   255→			Mode: filemode.Regular,
   256→			Hash: blobHash,
   257→		}
   258→	}
   259→
   260→	// Copy additional metadata files from directory if specified
   261→	if opts.MetadataDir != "" {
   262→		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
   263→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   264→		}
   265→	}
   266→
   267→	// Write metadata.json (with merged info if existing metadata present)
   268→	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
   269→}
   270→
   271→// writeTranscript writes the transcript file from in-memory content or file path.
   272→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   273→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   274→	transcript := opts.Transcript
   275→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   276→		var readErr error
   277→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   278→		if readErr != nil {
   279→			// Non-fatal: transcript may not exist yet
   280→			transcript = nil
   281→		}
   282→	}
   283→	if len(transcript) == 0 {
   284→		return nil
   285→	}
   286→
   287→	// Chunk the transcript if it's too large
   288→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   289→	if err != nil {
   290→		return fmt.Errorf("failed to chunk transcript: %w", err)
   291→	}
   292→
   293→	// Write chunk files
   294→	for i, chunk := range chunks {
   295→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   296→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   297→		if err != nil {
   298→			return err
   299→		}
   300→		entries[chunkPath] = object.TreeEntry{
   301→			Name: chunkPath,
   302→			Mode: filemode.Regular,
   303→			Hash: blobHash,
   304→		}
   305→	}
   306→
   307→	// Content hash for deduplication (hash of full transcript)
   308→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   309→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   310→	if err != nil {
   311→		return err
   312→	}
   313→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   314→		Name: basePath + paths.ContentHashFileName,
   315→		Mode: filemode.Regular,
   316→		Hash: hashBlob,
   317→	}
   318→	return nil
   319→}
