   321→// writeMetadataJSON writes the metadata.json file for the checkpoint.
   322→// If existingMetadata is provided, merges session info from the previous session(s).
   323→func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
   324→	// Note: Agents array is only populated during multi-session merge (below).
   325→	// For single-session checkpoints, we only set Agent (singular).
   326→	metadata := CommittedMetadata{
   327→		CheckpointID:                opts.CheckpointID,
   328→		SessionID:                   opts.SessionID,
   329→		Strategy:                    opts.Strategy,
   330→		CreatedAt:                   time.Now().UTC(),
   331→		Branch:                      opts.Branch,
   332→		CheckpointsCount:            opts.CheckpointsCount,
   333→		FilesTouched:                opts.FilesTouched,
   334→		Agent:                       opts.Agent,
   335→		Agents:                      nil, // Only set during multi-session merge
   336→		IsTask:                      opts.IsTask,
   337→		ToolUseID:                   opts.ToolUseID,
   338→		SessionCount:                1,
   339→		SessionIDs:                  []string{opts.SessionID},
   340→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
   341→		TranscriptLinesAtStart:      opts.TranscriptLinesAtStart,
   342→		TokenUsage:                  opts.TokenUsage,
   343→		InitialAttribution:          opts.InitialAttribution,
   344→	}
   345→
   346→	// Merge with existing metadata if present (multi-session checkpoint)
   347→	if existingMetadata != nil {
   348→		// Get existing session count (default to 1 for backwards compat)
   349→		existingCount := existingMetadata.SessionCount
   350→		if existingCount == 0 {
   351→			existingCount = 1
   352→		}
   353→		metadata.SessionCount = existingCount + 1
   354→
   355→		// Merge session IDs
   356→		existingIDs := existingMetadata.SessionIDs
   357→		if len(existingIDs) == 0 {
   358→			// Backwards compat: old metadata only had SessionID
   359→			existingIDs = []string{existingMetadata.SessionID}
   360→		}
   361→		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
   362→		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)
   363→
   364→		// Merge agents (deduplicated, preserving order)
   365→		existingAgents := existingMetadata.Agents
   366→		if len(existingAgents) == 0 && existingMetadata.Agent != "" {
   367→			// Backwards compat: old metadata only had Agent
   368→			existingAgents = []agent.AgentType{existingMetadata.Agent}
   369→		}
   370→		metadata.Agents = mergeAgents(existingAgents, opts.Agent)
   371→		// Keep Agent as the first agent for backwards compat
   372→		if len(metadata.Agents) > 0 {
   373→			metadata.Agent = metadata.Agents[0]
   374→		}
   375→
   376→		// Merge files touched (deduplicated)
   377→		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)
   378→
   379→		// Sum checkpoint counts
   380→		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
   381→
   382→		// Keep existing attribution - we calculated this for the first session based on all commits in the shadow branch already
   383→		if existingMetadata.InitialAttribution != nil {
   384→			metadata.InitialAttribution = existingMetadata.InitialAttribution
   385→		}
   386→	}
   387→
   388→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
   389→	if err != nil {
   390→		return fmt.Errorf("failed to marshal metadata: %w", err)
   391→	}
   392→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   393→	if err != nil {
   394→		return err
   395→	}
   396→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   397→		Name: basePath + paths.MetadataFileName,
   398→		Mode: filemode.Regular,
   399→		Hash: metadataHash,
   400→	}
   401→	return nil
   402→}
   403→
   404→// mergeFilesTouched combines two file lists, removing duplicates.
   405→func mergeFilesTouched(existing, additional []string) []string {
   406→	seen := make(map[string]bool)
   407→	var result []string
   408→
   409→	for _, f := range existing {
   410→		if !seen[f] {
   411→			seen[f] = true
   412→			result = append(result, f)
   413→		}
   414→	}
   415→	for _, f := range additional {
   416→		if !seen[f] {
   417→			seen[f] = true
   418→			result = append(result, f)
   419→		}
   420→	}
   421→
   422→	sort.Strings(result)
   423→	return result
   424→}
   425→
   426→// mergeAgents combines existing agents with a new agent, removing duplicates.
   427→// Preserves order (existing agents first, then new agent if not already present).
   428→func mergeAgents(existing []agent.AgentType, newAgent agent.AgentType) []agent.AgentType {
   429→	if newAgent == "" {
   430→		return existing
   431→	}
   432→
   433→	seen := make(map[agent.AgentType]bool)
   434→	var result []agent.AgentType
   435→
   436→	for _, a := range existing {
   437→		if !seen[a] {
   438→			seen[a] = true
   439→			result = append(result, a)
   440→		}
   441→	}
   442→
   443→	if !seen[newAgent] {
   444→		result = append(result, newAgent)
   445→	}
   446→
   447→	return result
   448→}
