   450→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
   451→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
   452→	blob, err := s.repo.BlobObject(hash)
   453→	if err != nil {
   454→		return nil, fmt.Errorf("failed to get blob: %w", err)
   455→	}
   456→
   457→	reader, err := blob.Reader()
   458→	if err != nil {
   459→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   460→	}
   461→	defer reader.Close()
   462→
   463→	var metadata CommittedMetadata
   464→	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
   465→		return nil, fmt.Errorf("failed to decode metadata: %w", err)
   466→	}
   467→
   468→	return &metadata, nil
   469→}
