   471→// archiveExistingSession moves existing session files to a numbered subfolder.
   472→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   473→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   474→	// Determine archive folder number
   475→	sessionCount := existingMetadata.SessionCount
   476→	if sessionCount == 0 {
   477→		sessionCount = 1 // backwards compat
   478→	}
   479→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   480→
   481→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   482→	filesToArchive := []string{
   483→		paths.MetadataFileName,
   484→		paths.TranscriptFileName,
   485→		paths.PromptFileName,
   486→		paths.ContextFileName,
   487→		paths.ContentHashFileName,
   488→	}
   489→
   490→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   491→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   492→	for srcPath := range entries {
   493→		if strings.HasPrefix(srcPath, chunkPrefix) {
   494→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   495→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   496→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   497→			}
   498→		}
   499→	}
   500→
   501→	// Move each file to archive folder
   502→	for _, filename := range filesToArchive {
   503→		srcPath := basePath + filename
   504→		if entry, exists := entries[srcPath]; exists {
   505→			// Add to archive location
   506→			dstPath := archivePath + filename
   507→			entries[dstPath] = object.TreeEntry{
   508→				Name: dstPath,
   509→				Mode: entry.Mode,
   510→				Hash: entry.Hash,
   511→			}
   512→			// Remove from original location (will be overwritten by new session)
   513→			delete(entries, srcPath)
   514→		}
   515→	}
   516→}
   517→
   518→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   519→// Returns sessions ordered by folder index (oldest first).
   520→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   521→	var archived []ArchivedSession
   522→
   523→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   524→	// The most recent session is at the root level (not archived).
   525→	// Session count N means there are N-1 archived sessions.
   526→	for i := 1; i < sessionCount; i++ {
   527→		folderName := strconv.Itoa(i)
   528→
   529→		// Try to get the archived session subtree
   530→		subTree, err := checkpointTree.Tree(folderName)
   531→		if err != nil {
   532→			continue // Folder doesn't exist, skip
   533→		}
   534→
   535→		session := ArchivedSession{
   536→			FolderIndex: i,
   537→		}
   538→
   539→		// Read metadata to get session ID
   540→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   541→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   542→				var metadata CommittedMetadata
   543→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   544→					session.SessionID = metadata.SessionID
   545→				}
   546→			}
   547→		}
   548→
   549→		// Read transcript (handles both chunked and non-chunked formats)
   550→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   551→			session.Transcript = transcript
   552→		}
   553→
   554→		// Read prompts
   555→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   556→			if content, contentErr := file.Contents(); contentErr == nil {
   557→				session.Prompts = content
   558→			}
   559→		}
   560→
   561→		// Only add if we got a transcript
   562→		if len(session.Transcript) > 0 {
   563→			archived = append(archived, session)
   564→		}
   565→	}
   566→
   567→	return archived
   568→}
