   615→
   616→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   617→// Returns nil, nil if the checkpoint doesn't exist.
   618→//
   619→
   620→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   621→	_ = ctx // Reserved for future use
   622→
   623→	tree, err := s.getSessionsBranchTree()
   624→	if err != nil {
   625→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   626→	}
   627→
   628→	checkpointPath := checkpointID.Path()
   629→	checkpointTree, err := tree.Tree(checkpointPath)
   630→	if err != nil {
   631→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   632→	}
   633→
   634→	result := &ReadCommittedResult{}
   635→
   636→	// Read metadata.json
   637→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   638→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   639→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   640→			json.Unmarshal([]byte(content), &result.Metadata)
   641→			result.Metadata.Strategy = trailers.NormalizeStrategyName(result.Metadata.Strategy)
   642→		}
   643→	}
   644→
   645→	// Read transcript (handles both chunked and non-chunked formats)
   646→	if transcript, err := readTranscriptFromTree(checkpointTree, result.Metadata.Agent); err == nil && transcript != nil {
   647→		result.Transcript = transcript
