   672→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   673→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   674→//
   675→
   676→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   677→	_ = ctx // Reserved for future use
