   687→	for _, bucketEntry := range tree.Entries {
   688→		if bucketEntry.Mode != filemode.Dir {
   689→			continue
   690→		}
   691→		// Bucket should be 2 hex chars
   692→		if len(bucketEntry.Name) != 2 {
   693→			continue
   694→		}
   695→
   696→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   697→		if treeErr != nil {
   698→			continue
   699→		}
   700→
   701→		// Each entry in the bucket is the remaining part of the checkpoint ID
   702→		for _, checkpointEntry := range bucketTree.Entries {
   703→			if checkpointEntry.Mode != filemode.Dir {
   704→				continue
   705→			}
