   707→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   708→			if cpTreeErr != nil {
   709→				continue
   710→			}
   711→
   712→			// Reconstruct checkpoint ID: <bucket><remaining>
   713→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   714→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   715→			if cpIDErr != nil {
   716→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   717→				continue
   718→			}
   719→
   720→			info := CommittedInfo{
   721→				CheckpointID: checkpointID,
   722→			}
   723→
   724→			// Get details from metadata file
   725→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   726→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   727→					var metadata CommittedMetadata
   728→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   729→						info.SessionID = metadata.SessionID
   730→						info.CreatedAt = metadata.CreatedAt
   731→						info.CheckpointsCount = metadata.CheckpointsCount
   732→						info.FilesTouched = metadata.FilesTouched
