   742→			checkpoints = append(checkpoints, info)
   743→		}
   744→	}
   745→
   746→	// Sort by time (most recent first)
   747→	sort.Slice(checkpoints, func(i, j int) bool {
   748→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   749→	})
