   851→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   852→	obj := repo.Storer.NewEncodedObject()
   853→	obj.SetType(plumbing.BlobObject)
   854→	obj.SetSize(int64(len(content)))
   855→
   856→	writer, err := obj.Writer()
   857→	if err != nil {
