   948→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
   949→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
   950→// The agentType is used for reassembling chunks in the correct format.
   951→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
   952→	// Collect all transcript-related files
   953→	var chunkFiles []string
   954→	var hasBaseFile bool
   955→
   956→	for _, entry := range tree.Entries {
   957→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
   958→			hasBaseFile = true
   959→		}
   960→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
   961→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
   962→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
   963→			if idx > 0 {
   964→				chunkFiles = append(chunkFiles, entry.Name)
   965→			}
   966→		}
   967→	}
   968→
