   970→	if len(chunkFiles) > 0 {
   971→		// Sort chunk files by index
   972→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
   973→
   974→		// Check if base file should be included as chunk 0.
   975→		// NOTE: This assumes the chunking convention where the unsuffixed file
   976→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
   977→		if hasBaseFile {
   978→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
   979→		}
   980→
   981→		var chunks [][]byte
   982→		for _, chunkFile := range chunkFiles {
   983→			file, err := tree.File(chunkFile)
   984→			if err != nil {
   985→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
   986→					slog.String("chunk_file", chunkFile),
   987→					slog.String("error", err.Error()),
