   990→			}
   991→			content, err := file.Contents()
   992→			if err != nil {
   993→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
   994→					slog.String("chunk_file", chunkFile),
   995→					slog.String("error", err.Error()),
   996→				)
   997→				continue
   998→			}
   999→			chunks = append(chunks, []byte(content))
  1000→		}
  1001→
  1002→		if len(chunks) > 0 {
  1003→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1004→			if err != nil {
  1005→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1006→			}
  1007→			return result, nil
  1008→		}
  1009→	}
  1010→
  1011→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1012→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1013→		if content, err := file.Contents(); err == nil {
  1014→			return []byte(content), nil
  1015→		}
  1016→	}
